<template>
  <ChatsMainHeader
    v-if="participantProfileProcessed"
    :data="participantProfileProcessed"
    :loading="isGettingParticipantProfile || isChatInfoLoading"
  />
  <Separator />
  <AppLoader v-if="isMessageProcessing || isCreatingDm" title="Creating chat" variant="table" class="w-full h-full" />
  <ChatsMain2 v-else :loading="isGettingChatId" loading-subject="chat information">
    <template #inputs>
      <ChatsInputs
        v-model:input-text="inputMessage"
        v-model:files="files"
        v-model:group="groupId"
        :loading="isCreatingDm || isSendingMessage || isMessageProcessing"
        :bucket="bucket"
        @send="handleSend"
      />
    </template>
  </ChatsMain2>
</template>

<script setup lang="ts">
import { useSendMessage } from '~/mutations/chats/sendMessage';
import { type SendMessageResponse } from '~/composables/supabase/useSendMessage';
import { useGetChatId } from '~/composables/supabase/useGetChatId';
import { useUserProfile } from '~/composables/supabase/useUserProfile';
import { useCreateDm } from '~/mutations/chats/createDm';
import type { GetChatInfoResponse, ChatType } from '~/composables/supabase/useChatInfo';
import type { SendMessageArgs } from '~/composables/supabase/useSendMessage';
import { useFileToChatProcessing } from '~/composables/supabase/fileToChatProcessing';

interface Props {
  chatInfoData: GetChatInfoResponse | undefined;
  isChatInfoLoading: boolean;
}

defineProps<Props>();

const route = useRoute();

const userIds = computed(() => route.query.users?.toString().split(',') || []);

async function navToDm(chatId: string) {
  await navigateTo({ name: 'chats-id', params: { id: chatId } });
}

const { data: chatIdData, isLoading: isGettingChatId } = useQuery({
  key: () => ['send.chat.id', userIds.value],
  query: async () => {
    const data = await useGetChatId({ other_user_ids: userIds.value });
    if (data.error) {
      console.error('Failed to get or create chat id', data.error);
      captureExceptionToSentry(new Error('Failed to get or create chat id: ' + data.error));
    }
    if (data?.data?.chat_id) await navToDm(data.data.chat_id);
    if (!data.data?.chat_id) return { ...data, data: { ...data.data, chat_id: null } };
  },
  enabled: () => !!userIds.value.length,
});

const { data: participantProfile, isLoading: isGettingParticipantProfile } = useQuery({
  key: () => ['send.user.profile', userIds.value],
  query: async () => useUserProfile(userIds.value[0]),
  enabled: () => !!userIds.value.length && chatIdData.value?.data.chat_id === null,
});

const participantProfileProcessed = computed(() => {
  const profileData = participantProfile.value?.data || null;
  if (!profileData) return null;
  const user = profileData.find((user) => user.id !== userId.value);
  if (!user) return null;
  return {
    avatarUrl: user.avatar_url || '',
    title: user.display_name,
    role: user.role,
    type: 'DM' as ChatType,
    id: user.id,
  };
});

const { createDm, isCreatingDm } = useCreateDm();
const { sendMessage, isSendingMessage } = useSendMessage();

const inputMessage = ref<string>('');
const isMessageProcessing = ref<boolean>(false);

const files = ref<UploadItem[]>([]);
const groupId = ref<string | null>(null);

const { userId } = useUserRole();
const { handleFiles } = useFileToChatProcessing();
const bucket = 'attachments';

async function handleSend(data: SendMessageArgs) {
  //TODO: handle situation when dm creates and other requests fails
  const response = await createDm({ p_user_b: userIds.value[0] }).catch((err) => {
    console.error(err);
    showToastError('Failed to create dm chat');
    captureExceptionToSentry(new Error('Failed to create dm chat: ' + err));
    return;
  });

  if (response?.data) {
    isMessageProcessing.value = true;
    if (files.value.length) {
      try {
        await handleFiles({
          chatId: response.data,
          files: files.value,
          userId: userId.value,
          groupId: data.attachment_group_id!,
        });
      } catch (err) {
        console.error(err);
        showToastError('Please try to reattach files', 'Failed to send message');
        isMessageProcessing.value = false;
        captureExceptionToSentry(new Error('Failed to move files from draft folder for message: ' + err));
        return;
      }
    }

    await sendMessage({ data: { ...data, chat_id: response.data } })
      .then(async (resp: SendMessageResponse) => {
        useQueryCache().setQueryData(['messages.id', response.data], () => {
          return {
            items: [resp.data],
            error: null,
            oldestId: null,
            newestId: null,
            hasOlder: false,
            hasNewer: false,
          };
        });
        useQueryCache().setQueryData(['chatParticipants.id', response.data], () => {
          return {
            ...participantProfile.value,
            data: [participantProfileProcessed.value],
          };
        });
        groupId.value = null;
        inputMessage.value = '';
        files.value = [];
        await navToDm(response.data); //TBD: maybe navigation should be calld not only in success send message case
      })
      .catch((err) => {
        showToastError('Failed to send message');
        console.error(err);
        captureExceptionToSentry(new Error('Failed to send message: ' + err));
      })
      .finally(() => {
        isMessageProcessing.value = false;
      });
  }
}
</script>
