import type { QueryData } from '@supabase/supabase-js';
import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

export type UserProfile = Database['private']['Tables']['profiles']['Row'];

export const useUserProfile = async (userId: string | null) => {
  if (!userId) return undefined;
  return withSupabase((supabase) => supabase.from('profiles').select().eq('id', userId));
};

export type GetUserProfileResponse = QueryData<ReturnType<typeof useUserProfile>>;
