import type { QueryData } from '@supabase/supabase-js';
import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

type GetChatIdArgs = Database['private']['CompositeTypes']['get_chat_id_input'];

export const useGetChatId = async (data: GetChatIdArgs) => {
  return withSupabase((supabase) => supabase.schema('private').rpc('get_chat_id', { input: data }));
};

export type GetMessagesResponse = QueryData<ReturnType<typeof useGetChatId>>;
