import { type CreateDmArgs, useCreateDmFunc } from '~/composables/supabase/useCreateDm';

export const useCreateDm = defineMutation(() => {
  const { mutateAsync: createDm, asyncStatus } = useMutation({
    mutation: (data: CreateDmArgs) => useCreateDmFunc(data),
    onSuccess: (response, params) => {
      if (response.error) {
        console.error('Failed to initiate chat:', response.error);
        throw new Error('Failed to initiate chat');
      }
    },
    onError: (err) => {
      showToastError(err);
    },
  });

  return {
    createDm,
    isCreatingDm: computed(() => asyncStatus.value === 'loading'),
  };
});
