import type { QueryData } from '@supabase/supabase-js';
import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

export type CreateDmArgs = Database['private']['Functions']['new_dm']['Args'];

export const useCreateDmFunc = async (data: CreateDmArgs) => {
  return withSupabase((supabase) => supabase.rpc('new_dm', data));
};

export type GetMessagesResponse = QueryData<ReturnType<typeof useCreateDmFunc>>;
